const fs = require('fs');
const { Document, Packer, Paragraph, TextRun, ImageRun, AlignmentType, BorderStyle,
  LevelFormat, ShadingType } = require('docx');

const FONT = 'Arial';
const NAVY = '333366';
const ph = (t) => new TextRun({ text: t, highlight: 'yellow', font: FONT, size: 22 });
const t = (s, o = {}) => new TextRun({ text: s, font: FONT, size: 22, ...o });
const p = (children, o = {}) => new Paragraph({ children, spacing: { after: 120 }, ...o });

const logo = fs.readFileSync('logo.png');

const doc = new Document({
  styles: { default: { document: { run: { font: FONT, size: 22 } } } },
  numbering: { config: [{ reference: 'pts', levels: [{ level: 0, format: LevelFormat.BULLET, text: '•',
    alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 400, hanging: 260 } } } }] }] },
  sections: [{
    properties: { page: { margin: { top: 1000, bottom: 1000, left: 1300, right: 1300 } } },
    children: [
      // Kopf: Logo + Absender
      new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { after: 60 },
        children: [new ImageRun({ type: 'png', data: logo, transformation: { width: 166, height: 62 } })] }),
      new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { after: 360 }, children: [
        ph('[Dein Name]'), t(' · Kolonnenshirt · ', { size: 18 }), ph('[Straße, PLZ Ort]'),
        t(' · ', { size: 18 }), ph('[Telefon]'), t(' · ', { size: 18 }), ph('[E-Mail]')] }),

      // Empfänger (aus dem Impressum)
      p([ph('[Firmenname laut Impressum]')], { spacing: { after: 0 } }),
      p([ph('[Straße Hausnummer]')], { spacing: { after: 0 } }),
      p([ph('[PLZ] Chemnitz')], { spacing: { after: 360 } }),

      new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { after: 240 }, children: [t('Chemnitz, '), ph('[Datum]')] }),

      // Betreff – klar als Werbung erkennbar
      p([t('Werbung: Firmenshirts mit Ihrem gestickten Logo', { bold: true, size: 26, color: NAVY })], { spacing: { after: 240 } }),

      p([t('Guten Tag,')]),
      p([t('ich verkaufe unter dem Namen Kolonnenshirt Firmenshirts mit gesticktem Logo, gemacht für kleine Handwerks- und Baubetriebe.')]),

      new Paragraph({ numbering: { reference: 'pts', level: 0 }, spacing: { after: 60 }, children: [
        t('5 Shirts mit Ihrem Logo: ', { bold: true }), t('109 Euro brutto')] }),
      new Paragraph({ numbering: { reference: 'pts', level: 0 }, spacing: { after: 60 }, children: [
        t('Ein Shirt nachbestellen: ', { bold: true }), t('29,90 Euro brutto')] }),
      new Paragraph({ numbering: { reference: 'pts', level: 0 }, spacing: { after: 60 }, children: [
        t('Gestickt wird erst, wenn Sie bestellen.', { bold: true })] }),
      new Paragraph({ numbering: { reference: 'pts', level: 0 }, spacing: { after: 200 }, children: [
        t('Versand: '), ph('[Versandkosten und Lieferzeit ergänzen]')] }),

      p([t('Wenn Sie Interesse haben, rufen Sie mich an oder schreiben Sie mir: '), ph('[Telefon]'), t(' oder '), ph('[E-Mail]'), t('.')]),
      p([t('Viele Grüße')], { spacing: { before: 200, after: 480 } }),
      p([ph('[Dein Name]'), t(', Kolonnenshirt')], { spacing: { after: 400 } }),

      // Pflichthinweis Art. 21 Abs. 4 DSGVO, getrennt vom übrigen Text
      new Paragraph({ border: { top: { style: BorderStyle.SINGLE, size: 6, color: '999999', space: 6 } },
        spacing: { before: 200, after: 60 },
        children: [t('Ihr Recht auf Widerspruch', { bold: true, size: 18 })] }),
      new Paragraph({ spacing: { after: 60 }, children: [
        t('Sie können der Nutzung Ihrer Daten für Werbung jederzeit widersprechen. Ein kurzer Anruf, eine E-Mail oder ein Brief an die Adresse oben genügt. Danach erhalten Sie von mir keine Werbung mehr.', { size: 18 })] }),
      new Paragraph({ children: [
        t('Ihre Firmenanschrift stammt aus ', { size: 18 }), ph('[Quelle, z. B. Ihrem Impressum]'),
        t('. Mehr zum Datenschutz: ', { size: 18 }), ph('[Link oder Hinweis zur Datenschutzerklärung]')] }),
    ],
  }],
});

Packer.toBuffer(doc).then((b) => fs.writeFileSync('Kolonnenshirt_Werbebrief.docx', b));
